settings.custom_css:
selector{
    background:
        radial-gradient(circle at top left,
            rgba(246,140,17,.08),
            transparent 40%),
        rgba(15,15,15,.4);

    backdrop-filter: blur(30px);
    -webkit-backdrop-filter: blur(30px);
}

selector .softlite-dynamic-card-box{
    position: relative;
    overflow: hidden;
    height: 100%;
    background: rgba(18,18,18,.45);
    border: 1px solid rgba(255,255,255,.12);
    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);

    transition: all .45s cubic-bezier(.4,0,.2,1);

    box-shadow:
        0 8px 32px rgba(0,0,0,.25),
        inset 0 1px 0 rgba(255,255,255,.08);
}

selector .softlite-dynamic-card-box:hover{
    transform: translateY(-10px);
    border-color: rgba(246,140,17,.35);

    box-shadow:
        0 20px 50px rgba(246,140,17,.18),
        0 10px 30px rgba(0,0,0,.35),
        inset 0 1px 0 rgba(255,255,255,.12);

    background: rgba(18,18,18,.65);
}

selector .softlite-dynamic-card-box::before{
    content:'';
    position:absolute;
    top:0;
    left:-150%;
    width:70%;
    height:100%;
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255,255,255,.12),
        transparent
    );

    transform: skewX(-25deg);
    transition: 0.8s;
}

selector .softlite-dynamic-card-box:hover::before{
    left:150%;
}

selector .znj5l3o6{
    transition: all .4s ease;
}

selector:hover .znj5l3o6{
    transform: scale(1.1);
    background: rgba(246,140,17,.15);
    border-color: rgba(246,140,17,.4);
}

selector .qxh96q6a,
selector .abcqf4bo{
    transition: all .35s ease;
}

selector:hover .qxh96q6a,
selector:hover .abcqf4bo{
    color:#F68C11;
    stroke:#F68C11;
}

selector .sxbut4x0{
    transition: all .35s ease;
}

selector:hover .sxbut4x0{
    color:#ffffff;
}

selector .c4cu1xrl{
    transition: all .35s ease;
}

selector:hover .c4cu1xrl{
    transform: translateX(8px);
}

